command:
foreach ($d in $dirs) {
  Set-Location C:/temp/x
}
Remove-Item -Recurse -Force state

try {
  Set-Location C:/temp/x
} catch {
  Write-Host no
}
Remove-Item -Recurse -Force state

if (Test-Path C:/temp/x)
{
  Set-Location C:/temp/x
}
Remove-Item -Recurse -Force state

[ -d build ] && {
  cd build
}
rm -rf state/views

go() {
  cd /tmp/x
}
echo 'x' > src/a.ts

case "$OSTYPE" in
  msys*) echo win ;;
  *) echo other ;;
esac
cd /tmp/w && echo 'x' > probe.js

if (-not (Test-Path $env:TEMP\w)) { New-Item -ItemType Directory $env:TEMP\w | Out-Null }
Set-Location $env:TEMP\w
'console.log(1)' | Set-Content probe.js

for ($i = 0; $i -lt 3; $i++) { node src/a.ts $i }
Set-Location $env:TEMP
'x' | Set-Content probe.js

if(Test-Path src){ ls src }
Set-Location $env:TEMP
'x' | Set-Content probe.js

if (Test-Path src)
{
  ls src
}
Set-Location $env:TEMP
'x' | Set-Content probe.js

f=src/a.ts; cat > "$f" <<'EOF'
export const a = 1;
EOF

cat > src/a.ts <<'EOF'
const s = "it's";
EOF

Get-ChildItem src -Recurse -Filter *.ts | ForEach-Object {
  $text = Get-Content $_.FullName -Raw
  $text = $text -replace 'oldName','newName'
  Set-Content -Path $_.FullName -Value $text -NoNewline
}

foreach ($f in (Get-ChildItem src -Filter *.ts)) {
  $c = [regex]::Replace((Get-Content $f.FullName -Raw), 'a', 'b')
  Out-File -FilePath $f.FullName -InputObject $c -Encoding utf8
}
